mapper.select:
/* Tbm01Mapper.selectTbmEduInfo */ SELECT A.CMPNY_CD AS cmpnyCd , A.MTRL_CD AS mtrlCd , A.TITLE AS title , A.CONTENTS AS contents , A.MTRL_TYPE AS mtrlType , A.USE_YN AS useYn , COUNT(B.MTRL_ITEM_CD) AS mtrlCnt /* 데이터 초기화용 값 */ , A.TITLE AS oriTitle , A.CONTENTS AS oriContents , A.MTRL_TYPE AS oriMtrlType , A.USE_YN AS oriUseYn
, FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'USER', A.INSERT_NO, NULL) AS insertNm , DATE_FORMAT(A.INSERT_DATE, '%Y-%m-%d %H:%i') AS insertDate FROM TB_TBM_EDU_MTRL A INNER JOIN TB_TBM_EDU_MTRL_ITEM B ON ( A.MTRL_CD = B.MTRL_CD AND B.USE_YN = 'Y' ) WHERE A.CMPNY_CD = #{gvCmpnyCd}
AND A.MTRL_CD = #{mtrlCd}
AND A.TITLE LIKE CONCAT('%', #{title}, '%')
AND A.MTRL_TYPE = #{mtrlType}
AND A.USE_YN = #{useYn}
GROUP BY A.CMPNY_CD , A.MTRL_CD , A.TITLE , A.CONTENTS , A.MTRL_TYPE , A.USE_YN

    /* Tbm01Mapper.selectMtrlCd */
    SELECT CONCAT(DATE_FORMAT(CURDATE(), '%y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'MTRL_CD'))
	FROM DUAL

    /* Tbm01Mapper.selectMtrlItemCd */
    SELECT CONCAT(DATE_FORMAT(CURDATE(), '%y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'MTRL_ITEM_CD'))
	FROM DUAL

mapper.update:
/* Tbm01Mapper.mergeTbmEduItemInfo */
INSERT INTO TB_TBM_EDU_MTRL_ITEM (
    MTRL_ITEM_CD
    , MTRL_CD
    , SORT_IDX
    , MTRL_ITEM_TYPE
    , MTRL_DESC
    , FILE_MGMT_CD
    , URL
    , USE_YN
    , INSERT_NO
    , UPDATE_NO
) VALUES (
    #{mtrlItemCd}
    , #{mtrlCd}
    , #{sortIdx}
    , #{mtrlItemType}
    , #{mtrlDesc}
    , #{fileMgmtCd}
    , #{url}
    , #{useYn}
    , #{gvUserCd}
    , #{gvUserCd}
) AS NEW
ON DUPLICATE KEY UPDATE
    MTRL_ITEM_TYPE   = NEW.MTRL_ITEM_TYPE
    , MTRL_DESC      = NEW.MTRL_DESC
    , FILE_MGMT_CD   = NEW.FILE_MGMT_CD
    , URL            = NEW.URL
    , USE_YN         = NEW.USE_YN
    , UPDATE_NO      = NEW.UPDATE_NO
    , UPDATE_DATE    = NOW()

/* Tbm01Mapper.mergeTbmEduInfo */
INSERT INTO TB_TBM_EDU_MTRL (
    MTRL_CD,
    CMPNY_CD,
    TITLE,
    CONTENTS,
    MTRL_TYPE,
    USE_YN,
    INSERT_NO,
    INSERT_DATE,
    UPDATE_NO,
    UPDATE_DATE
) VALUES (
    #{mtrlCd}
    , #{gvCmpnyCd}
    , #{title}
    , #{contents}
    , #{mtrlType}
    , #{useYn}
    , #{gvUserCd}
    , NOW()
    , #{gvUserCd}
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
    TITLE      		= NEW.TITLE
    , CONTENTS   	= NEW.CONTENTS
    , MTRL_TYPE  	= NEW.MTRL_TYPE
    , USE_YN     	= NEW.USE_YN
    , UPDATE_NO   	= NEW.UPDATE_NO
    , UPDATE_DATE 	= NOW()

mapper.delete:
/* Tbm01Mapper.deleteTbmEduItemInfo */
DELETE FROM TB_TBM_EDU_MTRL_ITEM
WHERE MTRL_ITEM_CD = #{mtrlItemCd}

/* Tbm01Mapper.deleteTbmEduInfo */
DELETE FROM TB_TBM_EDU_MTRL
WHERE MTRL_CD = #{mtrlCd}
  AND CMPNY_CD = #{gvCmpnyCd}
